export function rrf(lists: string[][], k = 60) {
  const score = new Map<string, number>();
  for (const list of lists)
    list.forEach((id, rank) => score.set(id, (score.get(id) ?? 0) + 1 / (k + rank + 1)));
  return [...score.entries()].sort((a, b) => b[1] - a[1]).map(([id]) => id);
}

async function runAgent(messages: Msg[], tools: Tool[], maxSteps = 15) {
  for (let step = 0; step < maxSteps; step++) {
    const res = await llm({ messages, tools });
    messages.push(res.message);
    if (!res.toolCalls?.length) return res.message.content; // final answer
    for (const call of res.toolCalls) {
      const result = await safeExecute(tools, call); // returns error text on failure
      messages.push({ role: 'tool', toolCallId: call.id, content: result });
    }
  }
  throw new Error('Agent exceeded max steps');
}

